const CURRENCIES = {
  USD:{ symbol:"$",  rate:0.19, label:"USD $" },
  EUR:{ symbol:"€",  rate:0.17, label:"EUR €" },
  BRL:{ symbol:"R$", rate:1,    label:"BRL R$" },
  GBP:{ symbol:"£",  rate:0.15, label:"GBP £" },
};

function fmtPrice(brl, cur) {
  const {symbol,rate} = CURRENCIES[cur];
  const v = (brl * rate).toFixed(0);
  return symbol+" "+v;
}

